"""Genera reporte_tecnico.pdf y la visualización exploratoria."""
from pathlib import Path
import json
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Image, Table,
                                TableStyle, PageBreak, KeepTogether)
from sklearn.datasets import load_breast_cancer

ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'evidencias'; REPORT=ROOT/'reportes'/'reporte_tecnico.pdf'
OUT.mkdir(exist_ok=True); REPORT.parent.mkdir(exist_ok=True)
df=pd.read_csv(ROOT/'datos'/'datos_limp'/'breast_cancer_wisconsin_limpio.csv')
# Gráfica exploratoria: balance de clases y rangos amplios de variables de tamaño.
fig,axs=plt.subplots(1,2,figsize=(11,4.3))
df.diagnostico.map({0:'Maligno (0)',1:'Benigno (1)'}).value_counts().reindex(['Maligno (0)','Benigno (1)']).plot(kind='bar',ax=axs[0],color=['#bf4b54','#4d83a8'])
axs[0].set_title('Distribución de diagnóstico');axs[0].set_ylabel('Muestras');axs[0].set_xlabel('');axs[0].tick_params(axis='x',rotation=0)
sns.boxplot(data=df[['mean_radius','mean_perimeter','mean_area']],ax=axs[1],color='#79a9a1',showfliers=True)
axs[1].set_title('Rangos y posibles valores extremos');axs[1].set_ylabel('Valor original (escalas distintas)');axs[1].tick_params(axis='x',rotation=20)
fig.suptitle('Exploración inicial del conjunto');fig.tight_layout();eda=OUT/'exploracion_datos.png';fig.savefig(eda,dpi=160,bbox_inches='tight');plt.close(fig)
metrics=pd.read_csv(OUT/'metricas_modelos.csv');stats=json.loads((OUT/'comparacion_estadistica.json').read_text())
features=load_breast_cancer().feature_names
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='TitleC',parent=styles['Title'],alignment=TA_CENTER,textColor=colors.HexColor('#143650'),spaceAfter=14)); styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=8,leading=10)); styles.add(ParagraphStyle(name='H2x',parent=styles['Heading2'],textColor=colors.HexColor('#1e6473'),spaceBefore=10))
doc=SimpleDocTemplate(str(REPORT),pagesize=letter,rightMargin=0.62*inch,leftMargin=0.62*inch,topMargin=0.58*inch,bottomMargin=0.58*inch)
story=[]
story += [Paragraph('Reporte técnico: comparación de clasificadores y MLflow',styles['TitleC']),Paragraph('Actividad 5 · Clasificación binaria · 18 de octubre de 2026',styles['Normal']),Spacer(1,10)]
story += [Paragraph('Resumen',styles['H2x']),Paragraph('Se compararon Regresión Logística y Random Forest sobre Breast Cancer Wisconsin Diagnostic. Se reservó un conjunto de prueba estratificado del 20%; la búsqueda de hiperparámetros optimizó ROC-AUC con validación cruzada estratificada de cinco folds. Con semilla 42, Regresión Logística obtuvo ROC-AUC de prueba 0.9954 y accuracy 0.9825; Random Forest obtuvo ROC-AUC 0.9937 y accuracy 0.9474. La diferencia en folds no fue estadísticamente significativa en la prueba t exploratoria (p=0.285). Este resultado académico no es una herramienta clínica.',styles['BodyText'])]
story += [Paragraph('1. Dataset y supuestos',styles['H2x']),Paragraph('Fuente: Wisconsin Diagnostic Breast Cancer (WDBC), UCI Machine Learning Repository; se carga desde el dataset de ejemplo distribuido con scikit-learn. Contiene 569 observaciones, 30 predictores numéricos calculados a partir de imágenes digitalizadas de aspiración con aguja fina y dos clases. La etiqueta se codifica como 0=maligno y 1=benigno; por ello precision/recall/F1 corresponden a benigno como clase positiva. La fuente UCI describe las 569 instancias y 30 atributos y enlaza el DOI 10.24432/C5DW2B.',styles['BodyText']),Paragraph('Supuestos: muestras independientes, predictores numéricos y etiqueta binaria válida. El dataset empaquetado en scikit-learn no incluye identificadores personales; no se infiere población clínica ni validez externa.',styles['BodyText']),Paragraph('Diccionario de datos',styles['H2x']),Paragraph('Etiqueta: diagnostico (0 maligno, 1 benigno). Cada uno de los 30 predictores mide una propiedad de los núcleos celulares: radius, texture, perimeter, area, smoothness, compactness, concavity, concave points, symmetry y fractal dimension, resumidas como mean, error (error estándar) y worst (valor peor/prominente). Nombres exactos de columnas: '+', '.join(features)+'.',styles['Small']),Image(str(eda),width=7.05*inch,height=2.75*inch)]
story += [Paragraph('2. Limpieza, estandarización y reglas',styles['H2x']),Paragraph('El script datos_prep.py exporta el conjunto de origen y genera el CSV limpio. Se normalizan nombres, se convierten predictores a numérico, se fuerza la etiqueta a entero, se eliminan duplicados y se valida que no haya nulos y que la etiqueta sea binaria. En el conjunto de origen no se detectan faltantes. El pipeline incluye imputación por mediana como salvaguarda; se ajusta solo en entrenamiento de cada fold. StandardScaler estandariza las variables dentro del pipeline de ambos modelos, evitando fuga de información. No hay predictores categóricos, así que no se requiere one-hot encoding. No se aplican reglas de negocio clínicas.',styles['BodyText']),Paragraph('3. Diseño experimental y modelos',styles['H2x']),Paragraph('Partición fija: 80% entrenamiento y 20% prueba, estratificada, random_state=42. GridSearchCV con StratifiedKFold(n_splits=5, shuffle=True, random_state=42), selección por ROC-AUC y refit en el conjunto de entrenamiento. Logistic Regression: C ∈ {0.1, 1, 10}, class_weight ∈ {None, balanced}, max_iter=3000. Random Forest: n_estimators ∈ {200, 400}, max_depth ∈ {None, 8}, min_samples_leaf ∈ {1, 2}, class_weight ∈ {None, balanced}.',styles['BodyText'])]
metric_rows=[['Modelo','Accuracy','Precision','Recall','F1','ROC-AUC prueba','ROC-AUC CV ± DE']]
for _,r in metrics.iterrows():metric_rows.append([r.modelo,*[f'{r[k]:.4f}' for k in ['accuracy','precision','recall','f1','roc_auc']],f'{r.cv_roc_auc_mean:.4f} ± {r.cv_roc_auc_std:.4f}'])
t=Table(metric_rows,repeatRows=1,colWidths=[1.15*inch,.72*inch,.72*inch,.72*inch,.62*inch,.86*inch,1.17*inch]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#143650')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,colors.grey),('FONTSIZE',(0,0),(-1,-1),7.5),('ALIGN',(1,1),(-1,-1),'CENTER'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#edf4f5')]),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
story += [Paragraph('4. Resultados',styles['H2x']),t,Spacer(1,7),Paragraph('Mejores parámetros según GridSearchCV:',styles['BodyText'])]
for _,r in metrics.iterrows():story.append(Paragraph(f'<b>{r.modelo}:</b> {r.mejores_parametros}',styles['Small']))
story += [Image(str(OUT/'curvas_roc.png'),width=4.8*inch,height=3.4*inch)]
cm1=Image(str(OUT/'confusion_LogisticRegression.png'),width=2.8*inch,height=2.25*inch); cm2=Image(str(OUT/'confusion_RandomForest.png'),width=2.8*inch,height=2.25*inch)
story.append(Table([[cm1,cm2]],colWidths=[3.05*inch,3.05*inch],style=TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),('ALIGN',(0,0),(-1,-1),'CENTER')])))
story.append(KeepTogether([Paragraph('5. Comparación estadística',styles['H2x']),Paragraph(f"Se compararon los cinco ROC-AUC de validación de la mejor configuración de cada familia con prueba t pareada bilateral: t={stats['t']:.3f}, p={stats['p_value']:.3f}, diferencia media (Logística − Random Forest)={stats['diferencia_media']:.4f}. No hay evidencia estadística suficiente de diferencia con α=0.05. Con cinco folds el análisis es exploratorio, la estimación tiene alta incertidumbre y los folds no son totalmente independientes.",styles['BodyText'])]))
story += [Paragraph('6. Seguimiento en MLflow y evidencias',styles['H2x']),Paragraph('train.py configura un tracking store local en mlruns/, crea un experimento, un run por modelo y un run de comparación. Cada run registra parámetros del split/CV/modelo, métricas estandarizadas, el modelo serializado, reporte de clasificación y matriz de confusión; el run final registra CSV, ROC, folds y contraste estadístico. Para inspeccionar: mlflow ui --backend-store-uri ./mlruns. En el entorno donde se generó este reporte, el índice de paquetes no permitió instalar MLflow; por ello aquí se validaron los cálculos de modelos y artefactos de análisis, pero no se produjo un run real ni una captura del panel. Al instalar requirements.txt, ejecutar train.py y tomar una captura de la UI se completa esa evidencia.',styles['BodyText']),Paragraph('7. Versionamiento, deuda técnica y MLOps',styles['H2x']),Paragraph('CHANGELOG.md documenta la versión inicial. Se versionan datos de entrada/salida como CSV y los resúmenes reproducibles; mlruns/ se excluye porque es un almacén local mutable. Deuda técnica: faltan lockfile de dependencias, pruebas automatizadas de esquema/datos, tracking remoto con autenticación, validación externa, análisis de calibración y umbrales, registro de modelo y política de promoción. Siguientes pasos MLOps: CI para reproducibilidad, control de versiones de dataset, pruebas de regresión, registro/model registry, seguimiento de drift y calidad, alertas y control de acceso.',styles['BodyText']),Paragraph('Referencias',styles['H2x']),Paragraph('UCI Machine Learning Repository. Breast Cancer Wisconsin (Diagnostic), DOI: 10.24432/C5DW2B. https://archive.ics.uci.edu/dataset/17/breast+cancer+wisconsin+diagnostic',styles['Small']),Paragraph('scikit-learn. load_breast_cancer dataset documentation. https://scikit-learn.org/stable/modules/generated/sklearn.datasets.load_breast_cancer.html',styles['Small'])]
def footer(canvas,doc):
 canvas.saveState();canvas.setFont('Helvetica',8);canvas.setFillColor(colors.grey);canvas.drawString(.62*inch,.35*inch,'Actividad 5 · reporte técnico');canvas.drawRightString(7.9*inch,.35*inch,str(doc.page));canvas.restoreState()
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(REPORT)
